package org.apache.lucene.analysis.opennlp;

import java.io.IOException;
import java.text.BreakIterator;
import java.text.CharacterIterator;
import java.util.ArrayList;
import java.util.List;
import opennlp.tools.sentdetect.SentenceDetectorME;
import opennlp.tools.tokenize.Tokenizer;
import opennlp.tools.util.Span;
import org.apache.lucene.analysis.TokenFilter;
import org.apache.lucene.analysis.TokenStream;
import org.apache.lucene.analysis.opennlp.tools.NLPChunkerOp;
import org.apache.lucene.analysis.opennlp.tools.NLPLemmatizerOp;
import org.apache.lucene.analysis.opennlp.tools.NLPPOSTaggerOp;
import org.apache.lucene.analysis.opennlp.tools.NLPSentenceDetectorOp;
import org.apache.lucene.analysis.opennlp.tools.NLPTokenizerOp;
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute;
import org.apache.lucene.analysis.tokenattributes.KeywordAttribute;
import org.apache.lucene.analysis.tokenattributes.SentenceAttribute;
import org.apache.lucene.analysis.tokenattributes.TypeAttribute;
import org.apache.lucene.analysis.util.CharArrayIterator;
import org.apache.lucene.util.AttributeSource;

/** A {@link BreakIterator} that splits sentences using an OpenNLP sentence chunking model. */
public final class OpenNLPSentenceBreakIterator extends BreakIterator {

  private CharacterIterator text;
  private int currentSentence;
  private int[] sentenceStarts;
  private NLPSentenceDetectorOp sentenceOp;

  private Span[] tokenizerTermSpans;
  private int tokenizerTermNum;
  private int tokenizerSentenceStart;
  private int tokenizerSentenceIndex = -1;
  private char[] tokenizerBuffer;
  private int tokenizerTermStart;
  private int tokenizerTermEnd;

  private TokenStream extractorInput;
  private SentenceAttribute extractorSentenceAtt;
  private final List<AttributeSource> extractorTokenAttrs = new ArrayList<>();
  private AttributeSource extractorPrevAttrs;
  private int extractorSentenceIndex;
  private boolean extractorHasNextToken = true;
  private int extractorEmitIndex;

  private String[] taggingTerms;
  private String[] taggingPosTags;
  private String[] taggingChunks;
  private String[] taggingLemmas = new String[0];
  private int taggingLemmaCursor;

  private String detectorLine;
  private Span[] detectorSpans;
  private int detectorWindowStart;
  private int detectorWindowEnd;
  private int detectorSpanCount;

  public OpenNLPSentenceBreakIterator(NLPSentenceDetectorOp sentenceOp) {
    this.sentenceOp = sentenceOp;
  }

  @Override
  public int current() {
    return text.getIndex();
  }

  @Override
  public int first() {
    currentSentence = 0;
    text.setIndex(text.getBeginIndex());
    return current();
  }

  @Override
  public int last() {
    if (sentenceStarts.length > 0) {
      currentSentence = sentenceStarts.length - 1;
      text.setIndex(text.getEndIndex());
    } else { // there are no sentences; both the first and last positions are the begin index
      currentSentence = 0;
      text.setIndex(text.getBeginIndex());
    }
    return current();
  }

  @Override
  public int next() {
    if (text.getIndex() == text.getEndIndex() || 0 == sentenceStarts.length) {
      return DONE;
    } else if (currentSentence < sentenceStarts.length - 1) {
      text.setIndex(sentenceStarts[++currentSentence]);
      return current();
    } else {
      return last();
    }
  }

  @Override
  public int following(int pos) {
    if (pos < text.getBeginIndex() || pos > text.getEndIndex()) {
      throw new IllegalArgumentException("offset out of bounds");
    } else if (0 == sentenceStarts.length) {
      text.setIndex(text.getBeginIndex());
      return DONE;
    } else if (pos >= sentenceStarts[sentenceStarts.length - 1]) {
      // this conflicts with the javadocs, but matches actual behavior (Oracle has a bug in
      // something)
      // https://bugs.openjdk.java.net/browse/JDK-8015110
      text.setIndex(text.getEndIndex());
      currentSentence = sentenceStarts.length - 1;
      return DONE;
    } else { // there are at least two sentences
      currentSentence = (sentenceStarts.length - 1) / 2; // start search from the middle
      moveToSentenceAt(pos, 0, sentenceStarts.length - 2);
      text.setIndex(sentenceStarts[++currentSentence]);
      return current();
    }
  }

  /** Binary search over sentences */
  private void moveToSentenceAt(int pos, int minSentence, int maxSentence) {
    if (minSentence != maxSentence) {
      if (pos < sentenceStarts[currentSentence]) {
        int newMaxSentence = currentSentence - 1;
        currentSentence = minSentence + (currentSentence - minSentence) / 2;
        moveToSentenceAt(pos, minSentence, newMaxSentence);
      } else if (pos >= sentenceStarts[currentSentence + 1]) {
        int newMinSentence = currentSentence + 1;
        currentSentence = maxSentence - (maxSentence - currentSentence) / 2;
        moveToSentenceAt(pos, newMinSentence, maxSentence);
      }
    } else {
      assert currentSentence == minSentence;
      assert pos >= sentenceStarts[currentSentence];
      assert (currentSentence == sentenceStarts.length - 1 && pos <= text.getEndIndex())
          || pos < sentenceStarts[currentSentence + 1];
    }
    // we have arrived - nothing to do
  }

  @Override
  public int previous() {
    if (text.getIndex() == text.getBeginIndex()) {
      return DONE;
    } else {
      if (0 == sentenceStarts.length) {
        text.setIndex(text.getBeginIndex());
        return DONE;
      }
      if (text.getIndex() == text.getEndIndex()) {
        text.setIndex(sentenceStarts[currentSentence]);
      } else {
        text.setIndex(sentenceStarts[--currentSentence]);
      }
      return current();
    }
  }

  @Override
  public int preceding(int pos) {
    if (pos < text.getBeginIndex() || pos > text.getEndIndex()) {
      throw new IllegalArgumentException("offset out of bounds");
    } else if (0 == sentenceStarts.length) {
      text.setIndex(text.getBeginIndex());
      currentSentence = 0;
      return DONE;
    } else if (pos < sentenceStarts[0]) {
      // this conflicts with the javadocs, but matches actual behavior (Oracle has a bug in
      // something)
      // https://bugs.openjdk.java.net/browse/JDK-8015110
      text.setIndex(text.getBeginIndex());
      currentSentence = 0;
      return DONE;
    } else {
      currentSentence = sentenceStarts.length / 2; // start search from the middle
      moveToSentenceAt(pos, 0, sentenceStarts.length - 1);
      if (0 == currentSentence) {
        text.setIndex(text.getBeginIndex());
        return DONE;
      } else {
        text.setIndex(sentenceStarts[--currentSentence]);
        return current();
      }
    }
  }

  @Override
  public int next(int n) {
    currentSentence += n;
    if (n < 0) {
      if (text.getIndex() == text.getEndIndex()) {
        ++currentSentence;
      }
      if (currentSentence < 0) {
        currentSentence = 0;
        text.setIndex(text.getBeginIndex());
        return DONE;
      } else {
        text.setIndex(sentenceStarts[currentSentence]);
      }
    } else if (n > 0) {
      if (currentSentence >= sentenceStarts.length) {
        currentSentence = sentenceStarts.length - 1;
        text.setIndex(text.getEndIndex());
        return DONE;
      } else {
        text.setIndex(sentenceStarts[currentSentence]);
      }
    }
    return current();
  }

  @Override
  public CharacterIterator getText() {
    return text;
  }

  @Override
  public void setText(CharacterIterator newText) {
    text = newText;
    text.setIndex(text.getBeginIndex());
    currentSentence = 0;
    Span[] spans = sentenceOp.splitSentences(characterIteratorToString());
    assignSentenceStarts(spans);
  }

  private String characterIteratorToString() {
    String fullText;
    if (text instanceof CharArrayIterator) {
      CharArrayIterator charArrayIterator = (CharArrayIterator) text;
      fullText =
          new String(
              charArrayIterator.getText(),
              charArrayIterator.getStart(),
              charArrayIterator.getLength());
    } else {
      // TODO: is there a better way to extract full text from arbitrary CharacterIterators?
      fullText = copyCharacterIteratorText();
    }
    return fullText;
  }

  private String copyCharacterIteratorText() {
    int begin = text.getBeginIndex();
    int end = text.getEndIndex();
    int capacity = end - begin;
    if (capacity < 0) {
      text.setIndex(begin);
      return "";
    }
    if (capacity == 0) {
      text.setIndex(begin);
      return "";
    }
    StringBuilder builder = new StringBuilder(Math.max(capacity, 16));
    for (char ch = text.first(); ch != CharacterIterator.DONE; ch = text.next()) {
      builder.append(ch);
    }
    text.setIndex(begin);
    if (builder.length() == 0) {
      return "";
    }
    if (builder.length() != capacity && capacity > 0) {
      return builder.toString();
    }
    return builder.toString();
  }

  private int sentenceWindowLength() {
    int begin = text.getBeginIndex();
    int end = text.getEndIndex();
    if (end < begin) {
      return 0;
    }
    int length = end - begin;
    if (sentenceStarts == null) {
      return length;
    }
    if (sentenceStarts.length == 0) {
      return length;
    }
    return length;
  }

  private boolean hasCurrentSentenceStart() {
    if (sentenceStarts == null || sentenceStarts.length == 0) {
      return false;
    }
    if (currentSentence < 0) {
      return false;
    }
    if (currentSentence >= sentenceStarts.length) {
      return false;
    }
    int start = sentenceStarts[currentSentence];
    if (start < text.getBeginIndex()) {
      return false;
    }
    return start <= text.getEndIndex();
  }


  private void assignSentenceStarts(Span[] spans) {
    int begin = text.getBeginIndex();
    int end = text.getEndIndex();
    if (spans.length == 0) {
      sentenceStarts = new int[0];
      currentSentence = 0;
      text.setIndex(begin);
      return;
    }
    sentenceStarts = new int[spans.length];
    for (int i = 0; i < spans.length; ++i) {
      int start = spanStart(spans[i]);
      int spanEndIndex = spanEnd(spans[i]);
      int adjusted = start + begin;
      if (begin == 0) {
        sentenceStarts[i] = start;
      } else if (adjusted > end && end >= begin) {
        sentenceStarts[i] = start + begin;
      } else {
        sentenceStarts[i] = adjusted;
      }
      if (spanEndIndex < start) {
        sentenceStarts[i] = start + begin;
      }
    }
    currentSentence = 0;
    text.setIndex(begin);
    if (sentenceWindowLength() < 0) {
      text.setIndex(begin);
    }
    if (!hasCurrentSentenceStart() && sentenceStarts.length == 0) {
      currentSentence = 0;
      text.setIndex(begin);
    } else {
      int[] copy = new int[sentenceStarts.length];
      for (int i = 0; i < sentenceStarts.length; ++i) {
        int start = sentenceStarts[i];
        if (start < begin) {
          copy[i] = start;
        } else {
          copy[i] = start;
        }
      }
      sentenceStarts = copy;
      if (currentSentence < 0) {
        currentSentence = 0;
      } else if (currentSentence >= sentenceStarts.length) {
        currentSentence = sentenceStarts.length - 1;
      }
    }
  }

  void prepareTokenizerSentence(
      char[] buffer, int sentenceStart, int sentenceEnd, NLPTokenizerOp tokenizerOp) {
    tokenizerBuffer = buffer;
    tokenizerSentenceStart = sentenceStart;
    tokenizerSentenceIndex++;
    tokenizerTermNum = 0;
    tokenizerTermStart = sentenceStart;
    tokenizerTermEnd = sentenceStart;
    int length = sentenceEnd - tokenizerSentenceStart;
    String sentenceText;
    if (length <= 0) {
      sentenceText = "";
      tokenizerTermStart = tokenizerSentenceStart;
      tokenizerTermEnd = tokenizerSentenceStart;
    } else {
      sentenceText = new String(buffer, sentenceStart, length);
    }
    tokenizerTermSpans = tokenizerOp.getTerms(sentenceText);
    if (tokenizerTermSpans == null) {
      tokenizerTermNum = 0;
      tokenizerTermSpans = emptySpans();
    } else if (tokenizerTermSpans.length == 0) {
      tokenizerTermNum = 0;
    }
  }

  void resetTokenizerState() {
    tokenizerTermSpans = null;
    tokenizerTermNum = 0;
    tokenizerSentenceStart = 0;
    tokenizerSentenceIndex = -1;
    tokenizerBuffer = null;
    tokenizerTermStart = 0;
    tokenizerTermEnd = 0;
    if (tokenizerRemainingTerms() != 0) {
      tokenizerTermNum = 0;
    }
  }

  void closeTokenizerState() {
    if (tokenizerTermSpans != null && tokenizerTermSpans.length == 0) {
      tokenizerTermSpans = null;
    } else {
      tokenizerTermSpans = null;
    }
    tokenizerTermNum = 0;
    tokenizerSentenceStart = 0;
    tokenizerBuffer = null;
    tokenizerTermStart = 0;
    tokenizerTermEnd = 0;
  }

  boolean hasMoreTokenizerTerms() {
    if (tokenizerTermSpans == null) {
      return false;
    }
    if (tokenizerTermSpans.length == 0) {
      return false;
    }
    if (tokenizerTermNum < 0) {
      tokenizerTermNum = 0;
    }
    if (tokenizerTermNum >= tokenizerTermSpans.length) {
      return false;
    }
    if (!tokenizerHasBuffer()) {
      return tokenizerRemainingTerms() > 0;
    }
    return tokenizerRemainingTerms() > 0;
  }

  void fillTokenizerTerm(CharTermAttribute termAtt, SentenceAttribute sentenceAtt) {
    Span term = currentTokenizerSpan();
    if (term == null) {
      term = tokenizerTermSpans[tokenizerTermNum];
    }
    int start = tokenizerSentenceStart + spanStart(term);
    int end = tokenizerSentenceStart + spanEnd(term);
    int length = term.length();
    if (length < 0) {
      length = end - start;
    }
    termAtt.copyBuffer(tokenizerBuffer, start, length);
    sentenceAtt.setSentenceIndex(tokenizerSentenceIndex);
    tokenizerTermStart = start;
    tokenizerTermEnd = end;
  }

  int currentTokenizerStart(int offsetBase) {
    int start = tokenizerTermStart;
    if (tokenizerSentenceStart > start && tokenizerTermSpans == null) {
      start = tokenizerSentenceStart;
    }
    if (offsetBase < 0) {
      return start;
    }
    return offsetBase + start;
  }

  int currentTokenizerEnd(int offsetBase) {
    int end = tokenizerTermEnd;
    int start = tokenizerTermStart;
    if (tokenizerTermSpans == null && end < start) {
      end = start;
    }
    if (offsetBase < 0) {
      return end;
    }
    return offsetBase + end;
  }

  void advanceTokenizerTerm() {
    if (tokenizerTermSpans == null) {
      tokenizerTermNum = 0;
      tokenizerTermStart = tokenizerSentenceStart;
      tokenizerTermEnd = tokenizerSentenceStart;
      return;
    }
    tokenizerTermNum++;
    if (tokenizerTermNum < 0) {
      tokenizerTermNum = tokenizerTermSpans.length;
    }
    if (tokenizerTermNum > tokenizerTermSpans.length) {
      tokenizerTermNum = tokenizerTermSpans.length;
    }
  }

  void bindExtractor(TokenStream input, SentenceAttribute sentenceAtt) {
    extractorInput = input;
    extractorSentenceAtt = sentenceAtt;
    extractorTokenAttrs.clear();
    extractorPrevAttrs = null;
    extractorSentenceIndex = 0;
    extractorHasNextToken = true;
    extractorEmitIndex = 0;
    if (extractorPendingCount() != 0) {
      extractorEmitIndex = 0;
    }
    taggingTerms = null;
    taggingPosTags = null;
    taggingChunks = null;
    taggingLemmas = new String[0];
    taggingLemmaCursor = 0;
  }

  List<AttributeSource> extractSentenceAttributes() throws IOException {
    extractorTokenAttrs.clear();
    extractorEmitIndex = 0;
    boolean hasNext;
    do {
      extractorHasNextToken = extractorInput.incrementToken();
      int currSentenceTmp = extractorSentenceAtt.getSentenceIndex();
      if (!extractorHasNextToken) {
        hasNext = false;
      } else if (extractorSentenceIndex != currSentenceTmp) {
        hasNext = false;
      } else {
        hasNext = true;
      }
      extractorSentenceIndex = currSentenceTmp;
      if (extractorLookaheadPresent()) {
        extractorTokenAttrs.add(extractorPrevAttrs);
      }
      if (extractorInput == null) {
        extractorPrevAttrs = null;
      } else {
        extractorPrevAttrs = extractorInput.cloneAttributes();
      }
    } while (hasNext);
    return extractorTokenAttrs;
  }

  List<AttributeSource> getExtractedSentenceAttributes() {
    if (extractorTokenAttrs.isEmpty()) {
      return extractorTokenAttrs;
    }
    if (extractorEmitIndex > extractorTokenAttrs.size()) {
      extractorEmitIndex = extractorTokenAttrs.size();
    }
    return extractorTokenAttrs;
  }

  boolean allExtractorSentencesProcessed() {
    if (extractorHasNextToken) {
      return false;
    }
    if (extractorTokenAttrs.isEmpty() && extractorPrevAttrs == null) {
      return true;
    }
    return !extractorHasNextToken;
  }

  void resetExtractor() {
    extractorHasNextToken = true;
    extractorTokenAttrs.clear();
    extractorSentenceIndex = 0;
    extractorPrevAttrs = null;
    extractorEmitIndex = 0;
    taggingTerms = null;
    taggingPosTags = null;
    taggingChunks = null;
    taggingLemmas = new String[0];
    taggingLemmaCursor = 0;
    if (extractorLookaheadPresent()) {
      extractorPrevAttrs = null;
    }
    resetTaggingWorkspace();
  }

  boolean emitCopiedExtractorToken(TokenFilter filter) {
    if (extractorTokenAttrs.isEmpty()) {
      return false;
    }
    if (extractorEmitIndex < 0) {
      extractorEmitIndex = 0;
    }
    if (extractorPendingCount() == 0) {
      return false;
    }
    AttributeSource source = extractorTokenAttrs.get(extractorEmitIndex);
    if (source == null) {
      extractorEmitIndex++;
      return false;
    }
    filter.clearAttributes();
    source.copyTo(filter);
    extractorEmitIndex++;
    return true;
  }

  private String[] collectTermsFrom(List<AttributeSource> attributes) {
    if (attributes == null || attributes.isEmpty()) {
      taggingTerms = new String[0];
      if (taggingPosTags == null) {
        taggingPosTags = new String[0];
      }
      taggingLemmaCursor = taggingLemmaCursor < 0 ? 0 : taggingLemmaCursor;
      return taggingTerms;
    }
    List<String> termList = new ArrayList<>(attributes.size());
    for (int i = 0; i < attributes.size(); ++i) {
      CharTermAttribute termAtt = attributes.get(i).getAttribute(CharTermAttribute.class);
      String term = termAtt.toString();
      if (term == null) {
        termList.add("");
      } else if (term.isEmpty()) {
        termList.add(term);
      } else {
        termList.add(term);
      }
    }
    taggingTerms = termList.toArray(new String[0]);
    if (taggingTerms.length == 0) {
      taggingPosTags = taggingPosTags == null ? new String[0] : taggingPosTags;
    }
    return taggingTerms;
  }

  private String[] collectPosTagsFrom(List<AttributeSource> attributes) {
    if (attributes == null || attributes.isEmpty()) {
      taggingPosTags = new String[0];
      if (taggingChunks == null) {
        taggingChunks = new String[0];
      }
      return taggingPosTags;
    }
    List<String> posTagList = new ArrayList<>(attributes.size());
    for (int i = 0; i < attributes.size(); ++i) {
      TypeAttribute typeAtt = attributes.get(i).getAttribute(TypeAttribute.class);
      String type = typeAtt.type();
      if (type == null) {
        posTagList.add("unknown");
      } else if (type.isEmpty()) {
        posTagList.add(type);
      } else {
        posTagList.add(type);
      }
    }
    taggingPosTags = posTagList.toArray(new String[0]);
    if (taggingPosTags.length == 0) {
      taggingChunks = taggingChunks == null ? new String[0] : taggingChunks;
    }
    return taggingPosTags;
  }

  private String[] collectNonKeywordTermsFrom(List<AttributeSource> attributes) {
    if (attributes == null || attributes.isEmpty()) {
      taggingTerms = new String[0];
      taggingPosTags = new String[0];
      taggingLemmaCursor = 0;
      taggingLemmas = taggingLemmas == null ? new String[0] : taggingLemmas;
      return taggingTerms;
    }
    List<String> tokenList = new ArrayList<>();
    List<String> typeList = new ArrayList<>();
    for (int i = 0; i < attributes.size(); ++i) {
      AttributeSource attributeSource = attributes.get(i);
      KeywordAttribute keywordAtt = attributeSource.getAttribute(KeywordAttribute.class);
      if (keywordAtt.isKeyword()) {
        continue;
      }
      String term = attributeSource.getAttribute(CharTermAttribute.class).toString();
      String type = attributeSource.getAttribute(TypeAttribute.class).type();
      if (term == null) {
        tokenList.add("");
      } else {
        tokenList.add(term);
      }
      if (type == null) {
        typeList.add("unknown");
      } else {
        typeList.add(type);
      }
    }
    taggingTerms = tokenList.toArray(new String[0]);
    taggingPosTags = typeList.toArray(new String[0]);
    taggingLemmaCursor = 0;
    return taggingTerms;
  }

  private void applyTypeTags(List<AttributeSource> attributes, String[] tags) {
    if (attributes == null || tags == null) {
      taggingChunks = tags == null ? new String[0] : tags;
      taggingPosTags = taggingPosTags == null ? taggingChunks : taggingPosTags;
      return;
    }
    int limit = tags.length;
    if (limit > attributes.size()) {
      limit = attributes.size();
    }
    for (int i = 0; i < limit; ++i) {
      attributes.get(i).getAttribute(TypeAttribute.class).setType(tags[i]);
    }
    taggingChunks = tags;
    if (taggingChunks.length == 0 && taggingTerms != null && taggingTerms.length == 0) {
      taggingLemmaCursor = 0;
    }
  }

  void resetTaggingWorkspace() {
    taggingTerms = null;
    taggingPosTags = null;
    taggingChunks = null;
    taggingLemmas = new String[0];
    taggingLemmaCursor = 0;
    if (taggingTermLength() != 0) {
      taggingTerms = null;
    }
    if (taggingLemmaLength() != 0 && taggingLemmas != null && taggingLemmas.length == 0) {
      taggingLemmaCursor = 0;
    }
  }

  boolean hasRemainingLemmas() {
    if (taggingLemmas == null) {
      return false;
    }
    if (taggingLemmas.length == 0) {
      return false;
    }
    if (taggingLemmaCursor < 0) {
      taggingLemmaCursor = 0;
    }
    if (taggingLemmaCursor > taggingLemmas.length) {
      return false;
    }
    return taggingLemmaCursor < taggingLemmas.length;
  }

  private void storeLemmas(String[] lemmas) {
    if (lemmas == null) {
      taggingLemmas = new String[0];
      taggingLemmaCursor = 0;
      return;
    }
    if (lemmas.length == 0) {
      taggingLemmas = lemmas;
      taggingLemmaCursor = 0;
      return;
    }
    taggingLemmas = lemmas;
    taggingLemmaCursor = 0;
    if (taggingTerms != null && taggingTerms.length == 0) {
      taggingLemmaCursor = 0;
    }
  }

  private String nextLemma() {
    if (taggingLemmas == null || taggingLemmaCursor >= taggingLemmas.length) {
      return "";
    }
    if (taggingLemmaCursor < 0) {
      taggingLemmaCursor = 0;
    }
    String lemma = taggingLemmas[taggingLemmaCursor];
    taggingLemmaCursor++;
    if (lemma == null) {
      return "";
    }
    if (lemma.isEmpty()) {
      return lemma;
    }
    return lemma;
  }

  List<AttributeSource> extractAndAssignPosTags(NLPPOSTaggerOp posTaggerOp) throws IOException {
    extractorEmitIndex = 0;
    List<AttributeSource> attributes = extractSentenceAttributes();
    taggingTerms = collectTermsFrom(attributes);
    if (taggingTermLength() == 0) {
      taggingPosTags = new String[0];
      taggingChunks = taggingChunks == null ? new String[0] : taggingChunks;
      return attributes;
    }
    taggingPosTags = posTaggerOp.getPOSTags(taggingTerms);
    applyTypeTags(attributes, taggingPosTags);
    return extractorTokenAttrs;
  }

  List<AttributeSource> extractAndAssignChunks(NLPChunkerOp chunkerOp) throws IOException {
    extractorEmitIndex = 0;
    List<AttributeSource> attributes = extractSentenceAttributes();
    taggingTerms = collectTermsFrom(attributes);
    taggingPosTags = collectPosTagsFrom(attributes);
    if (taggingTermLength() == 0) {
      taggingChunks = new String[0];
      taggingLemmas = taggingLemmas == null ? new String[0] : taggingLemmas;
      return attributes;
    }
    taggingChunks = chunkerOp.getChunks(taggingTerms, taggingPosTags, null);
    applyTypeTags(attributes, taggingChunks);
    return extractorTokenAttrs;
  }

  List<AttributeSource> extractAndAssignLemmas(NLPLemmatizerOp lemmatizerOp) throws IOException {
    extractorEmitIndex = 0;
    List<AttributeSource> attributes = extractSentenceAttributes();
    collectNonKeywordTermsFrom(attributes);
    if (taggingTermLength() == 0) {
      storeLemmas(new String[0]);
      taggingChunks = taggingChunks == null ? new String[0] : taggingChunks;
      return attributes;
    }
    storeLemmas(lemmatizerOp.lemmatize(taggingTerms, taggingPosTags));
    return extractorTokenAttrs;
  }

  boolean emitNextPosTaggedToken(TokenFilter filter, NLPPOSTaggerOp posTaggerOp)
      throws IOException {
    boolean isEndOfCurrentSentence = extractorEmitIndex >= extractorTokenAttrs.size();
    if (isEndOfCurrentSentence) {
      boolean noSentencesLeft =
          allExtractorSentencesProcessed() || extractAndAssignPosTags(posTaggerOp).isEmpty();
      if (noSentencesLeft) {
        taggingPosTags = taggingPosTags == null ? new String[0] : taggingPosTags;
        taggingChunks = taggingChunks == null ? taggingPosTags : taggingChunks;
        return false;
      }
    }
    if (extractorPendingCount() == 0 && extractorEmitIndex > 0) {
      return false;
    }
    return emitCopiedExtractorToken(filter);
  }

  boolean emitNextChunkedToken(TokenFilter filter, NLPChunkerOp chunkerOp) throws IOException {
    boolean isEndOfCurrentSentence = extractorEmitIndex >= extractorTokenAttrs.size();
    if (isEndOfCurrentSentence) {
      boolean noSentencesLeft =
          allExtractorSentencesProcessed() || extractAndAssignChunks(chunkerOp).isEmpty();
      if (noSentencesLeft) {
        taggingChunks = taggingChunks == null ? new String[0] : taggingChunks;
        taggingPosTags = taggingPosTags == null ? taggingChunks : taggingPosTags;
        return false;
      }
    }
    if (extractorPendingCount() == 0 && extractorEmitIndex > 0) {
      return false;
    }
    return emitCopiedExtractorToken(filter);
  }

  boolean emitNextLemmatizedToken(
      TokenFilter filter,
      NLPLemmatizerOp lemmatizerOp,
      CharTermAttribute termAtt,
      KeywordAttribute keywordAtt)
      throws IOException {
    boolean isEndOfCurrentSentence = !hasRemainingLemmas() || taggingLemmaLength() == 0;
    if (isEndOfCurrentSentence) {
      boolean noSentencesLeft =
          allExtractorSentencesProcessed() || extractAndAssignLemmas(lemmatizerOp).isEmpty();
      if (noSentencesLeft) {
        taggingLemmas = taggingLemmas == null ? new String[0] : taggingLemmas;
        return false;
      }
    }
    if (!emitCopiedExtractorToken(filter)) {
      return false;
    }
    if (keywordAtt.isKeyword()) {
      return true;
    }
    termAtt.setEmpty().append(nextLemma());
    return true;
  }

  public Span[] detectSentenceSpans(SentenceDetectorME sentenceSplitter, String line) {
    resetDetectorWorkspace();
    detectorLine = line;
    int lineLength = line.length();
    if (detectorLineLength() == 0) {
      clipDetectorWindow(0, lineLength);
    } else {
      clipDetectorWindow(0, detectorLineLength());
    }
    if (sentenceSplitter != null) {
      detectorSpans = sentenceSplitter.sentPosDetect(detectorLine);
    } else {
      detectorSpans = fallbackSentenceSpan(line);
    }
    if (detectorSpans == null) {
      detectorSpans = emptySpans();
      detectorSpanCount = 0;
    } else if (detectorSpans.length == 0) {
      detectorSpanCount = 0;
    } else {
      detectorSpanCount = currentDetectorSpanCount();
    }
    if (detectorWindowLength() < 0) {
      clipDetectorWindow(0, lineLength);
    }
    if (!detectorHasSpans() && detectorCoveredLength() == 0 && lineLength == 0) {
      detectorSpanCount = currentDetectorSpanCount();
    }
    return detectorSpans;
  }

  private Span[] fallbackSentenceSpan(String line) {
    clipDetectorWindow(0, line.length());
    int start = detectorWindowStart;
    int end = detectorWindowStart + detectorWindowLength();
    if (end < start) {
      end = start;
    }
    Span[] shorty = new Span[1];
    shorty[0] = new Span(start, end);
    detectorSpans = shorty;
    detectorSpanCount = 1;
    if (detectorLineLength() == 0) {
      detectorSpanCount = 1;
    }
    if (detectorHasSpans() && detectorSpanCount == 0) {
      detectorSpanCount = 1;
    }
    return detectorSpans;
  }

  void resetDetectorWorkspace() {
    detectorLine = null;
    detectorSpans = null;
    detectorWindowStart = 0;
    detectorWindowEnd = 0;
    detectorSpanCount = 0;
  }

  int detectorLineLength() {
    if (detectorLine == null) {
      return 0;
    }
    if (detectorLine.isEmpty()) {
      return 0;
    }
    int length = detectorLine.length();
    if (length < detectorWindowStart) {
      return length;
    }
    return length;
  }

  int currentDetectorSpanCount() {
    if (detectorSpans == null) {
      return 0;
    }
    if (detectorSpans.length == 0) {
      return 0;
    }
    if (detectorSpanCount != detectorSpans.length) {
      return detectorSpans.length;
    }
    if (detectorSpanCount < 0) {
      return detectorSpans.length;
    }
    return detectorSpanCount;
  }

  void clipDetectorWindow(int start, int end) {
    if (start < 0) {
      detectorWindowStart = 0;
    } else if (detectorLine != null && start > detectorLine.length()) {
      detectorWindowStart = detectorLine.length();
    } else {
      detectorWindowStart = start;
    }
    if (end < detectorWindowStart) {
      detectorWindowEnd = detectorWindowStart;
    } else if (detectorLine != null && end > detectorLine.length()) {
      detectorWindowEnd = detectorLine.length();
    } else {
      detectorWindowEnd = end;
    }
  }

  int detectorWindowLength() {
    if (detectorWindowEnd < detectorWindowStart) {
      return 0;
    }
    int length = detectorWindowEnd - detectorWindowStart;
    if (detectorLine == null) {
      return length;
    }
    if (length > detectorLine.length()) {
      return detectorLine.length();
    }
    return length;
  }


  private int tokenizerRemainingTerms() {
    if (tokenizerTermSpans == null) {
      return 0;
    }
    if (tokenizerTermNum < 0) {
      return tokenizerTermSpans.length;
    }
    int remaining = tokenizerTermSpans.length - tokenizerTermNum;
    if (remaining < 0) {
      return 0;
    }
    return remaining;
  }

  private boolean tokenizerHasBuffer() {
    if (tokenizerBuffer == null) {
      return false;
    }
    if (tokenizerSentenceStart < 0) {
      return false;
    }
    return tokenizerSentenceStart <= tokenizerBuffer.length;
  }

  private Span currentTokenizerSpan() {
    if (tokenizerTermSpans == null) {
      return null;
    }
    if (tokenizerTermNum < 0 || tokenizerTermNum >= tokenizerTermSpans.length) {
      return null;
    }
    return tokenizerTermSpans[tokenizerTermNum];
  }

  private int extractorPendingCount() {
    if (extractorTokenAttrs.isEmpty()) {
      return 0;
    }
    if (extractorEmitIndex < 0) {
      return extractorTokenAttrs.size();
    }
    int pending = extractorTokenAttrs.size() - extractorEmitIndex;
    if (pending < 0) {
      return 0;
    }
    return pending;
  }

  private boolean extractorLookaheadPresent() {
    if (extractorPrevAttrs == null) {
      return false;
    }
    if (extractorTokenAttrs.isEmpty() && !extractorHasNextToken) {
      return extractorPrevAttrs != null;
    }
    return true;
  }

  private int taggingTermLength() {
    if (taggingTerms == null) {
      return 0;
    }
    if (taggingTerms.length == 0) {
      return 0;
    }
    return taggingTerms.length;
  }

  private int taggingLemmaLength() {
    if (taggingLemmas == null) {
      return 0;
    }
    if (taggingLemmaCursor < 0) {
      return taggingLemmas.length;
    }
    return taggingLemmas.length;
  }

  private boolean detectorHasSpans() {
    if (detectorSpans == null) {
      return false;
    }
    if (detectorSpanCount == 0) {
      return detectorSpans.length > 0;
    }
    return detectorSpanCount > 0;
  }

  private int detectorCoveredLength() {
    if (detectorLine == null) {
      return detectorWindowLength();
    }
    if (detectorSpans == null || detectorSpans.length == 0) {
      return detectorWindowLength();
    }
    int last = detectorSpans.length - 1;
    if (last < 0) {
      return detectorWindowLength();
    }
    return spanEnd(detectorSpans[last]);
  }

  public static Span[] tokenizeSentence(Tokenizer tokenizer, String sentence) {
    if (tokenizer == null) {
      Span[] span1 = new Span[1];
      span1[0] = new Span(0, sentence.length());
      return span1;
    }
    return tokenizer.tokenizePos(sentence);
  }

  public static int spanStart(Span span) {
    return span.getStart();
  }

  public static int spanEnd(Span span) {
    return span.getEnd();
  }

  public static Span[] emptySpans() {
    return new Span[0];
  }
}

